        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Ach der unseelige Ehrgeiz, er ist ein Gift für alle Freuden.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Denn nicht durch Worte, aber durch Handlungen, zeigt sich wahre Treue und wahre Liebe.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Ich erkenne nur ein höchstes Gesetz an, die Rechtschaffenheit, und die Politik kennt nur ihren Vorteil.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Mit demselben Gefühle, mit welchem du bei dem Abendmahle das Brot nimmst aus der Hand des Priesters, mit demselben Gefühle, sage ich, erwürgt der Mexikaner seinen Bruder vor dem Altar seines Götzen.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Nie in meinem Leben, und wenn das Schicksal noch so sehr drängte, werde ich etwas tun, das meinen inneren Forderungen, sei es auch noch so leise, widerspräche.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Der Staat sichert uns unser Eigentum, unsre Ehre und unser Leben, wer sichert uns aber unser inneres Glück zu, wenn es die Vernunft nicht tut?", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Die Wahrheit ist, daß mir auf Erden nicht zu helfen war.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Kann man auch nur den Gedanken wagen, glücklich zu sein, wenn alles in Elend darnieder liegt?", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Lerne auch mit dem Zarten umzugehen.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Das Wissen macht uns weder besser, noch glücklicher.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Wenn wir von den Dichtern verlangen wollen, dass sie so idealisch sein sollen wie ihre Helden, wird es noch Dichter geben?", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Die Welt ist groß, man kann sich darin wohl vergessen.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Und was ist des Strebens wert, wenn es die Liebe nicht ist!", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Der Mensch wirft alles, was er sein nennt, in eine Pfütze, aber kein Gefühl.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Zum Stolpern brauchts nicht mehr als Füß.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Ich? die Spur? Bin ich der Teufel? Ist das ein Pferdefuß?", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "In Staub mit allen Feinden Brandenburgs!", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Komm, weine nicht; Du bist so werth mir, wie die Treue selbst!", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Und der im Leben tausendmal gesiegt, Er wird auch im Tod zu siegen wissen!", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Wer heut sein Haupt noch auf der Schulter trägt, Hängt es schon morgen zitternd auf den Leib, Und übermorgen liegts bei seiner Ferse.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Zwar, eine Sonne, sagt man, scheint dort auch Und über buntre Felder noch, als hier: Ich glaubs! nur Schade, daß das Auge modert, Das diese Herrlichkeit erblicken soll.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Schlagt ihn todt! Das Weltgericht fragt euch nach der Ursach nicht.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Torheit, du regierst die Welt, und dein Sitz ist ein schöner weiblicher Mund!", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Und siehe da, wenn ich mit meiner Schwester davon rede, welche hinter mir sitzt, und arbeitet, so erfahre ich, was ich durch ein vielleicht stundenlanges Brüten nicht herausgebracht haben würde.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Witz, wenn du dich in die Luft erhebst: wie stehen die Weisen und blicken dir nach!", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Dem Durstigen kommt es, als solchem, auf die Schale nicht an, sondern auf die Früchte, die man ihm darin bringt.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Der Tugend folgt die Belohnung, dem Laster die Strafe.", Author = "Heinrich von Kleist" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_von_Kleist", Text = "Was man dem Volke dreimal sagt, hält das Volk für wahr.", Author = "Heinrich von Kleist" },
